cd /workspace && node -e "
const mammoth = require('mammoth');
const fs = require('fs');
const path = require('path');

const docxDir = 'testbed/docs';
const files = fs.readdirSync(docxDir).filter(f => f.endsWith('.docx'));

(async () => {
  let output = '';
  for (const file of files) {
    const filePath = path.join(docxDir, file);
    const result = await mammoth.extractRawText({ path: filePath });
    output += '=== ' + file + ' ===\n\n' + result.value.trim() + '\n\n';
  }
  fs.writeFileSync('extracted_paragraphs.txt', output);
  console.log(output);
})();
"

